import ExpenseItem from "./ExpenseItem";

function ExpenseList({ expenses, fetchExpenses,setEditExpense }) {

  return (

    <div>

      {expenses.map((expense) => (

        <ExpenseItem
          key={expense._id}
          expense={expense}
          fetchExpenses={fetchExpenses}
          setEditExpense={setEditExpense}

        />

      ))}

    </div>

  );

}

export default ExpenseList;
